package com.unrealtrainmod.blueprint;

import java.util.List;
import java.util.UUID;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;

/** Only graph-local anchors cross the input boundary; world nodes are generated by the server. */
public record BlueprintPlacementRequest(List<List<Anchor>> tracks, double spacing, boolean startB, boolean reverse) {
    public record Anchor(UUID segment, double distance) {}
    public BlueprintPlacementRequest { tracks = tracks.stream().map(List::copyOf).toList(); }
    public CompoundTag save() {
        var tag = new CompoundTag(); tag.putDouble("Spacing", spacing); tag.putBoolean("StartB", startB); tag.putBoolean("Reverse", reverse);
        var lines = new ListTag();
        for (var line : tracks) {
            var t = new CompoundTag(); var points = new ListTag();
            for (var a : line) { var p = new CompoundTag(); p.putUUID("Segment", a.segment); p.putDouble("Distance", a.distance); points.add(p); }
            t.put("Points", points); lines.add(t);
        }
        tag.put("Bindings", lines); return tag;
    }
    public static BlueprintPlacementRequest load(CompoundTag tag) {
        double spacing = tag.getDouble("Spacing"); var bindings = tag.getList("Bindings", 10);
        if (!Double.isFinite(spacing) || spacing < .01 || spacing > 256 || bindings.size() > BlueprintDefinition.MAX_TRACKS)
            throw new IllegalArgumentException("spacing");
        var lines = bindings.stream().map(t -> {
            var points = ((CompoundTag)t).getList("Points", 10);
            if (points.size() > 256) throw new IllegalArgumentException("limit");
            return points.stream().map(p -> {
                var a = (CompoundTag)p; double distance = a.getDouble("Distance");
                if (!Double.isFinite(distance) || distance < 0) throw new IllegalArgumentException("path");
                return new Anchor(a.getUUID("Segment"), distance);
            }).toList();
        }).toList();
        return new BlueprintPlacementRequest(lines, spacing, tag.getBoolean("StartB"), tag.getBoolean("Reverse"));
    }
}
